/* @component: script-all-inputs */
(function () {
  function initAllInputs() {
    document.querySelectorAll('.js-container-input, fieldset').forEach(function (fs) {
      if (fs.dataset.initialized === 'true') return;
      fs.dataset.initialized = 'true';
      const label = fs.querySelector('label');
      const legendSpan = fs.querySelector('legend span');
      if (label && legendSpan) {
        legendSpan.textContent = label.textContent;
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAllInputs);
  } else {
    initAllInputs();
  }
  setTimeout(initAllInputs, 300);
})();
/* @end: script-all-inputs */
